#![allow(unused_imports)]
use verus::*;

//------------------------------------------------------------------------------
// Specification for `copy`: we require nothing, and we ensure that the
// returned Vec has exactly the same sequence of u64s as `a`.
// In Verus we write `a@` for the mathematical sequence view of `a`,
// and `result@` for the sequence view of the returned Vec.
//------------------------------------------------------------------------------

#[requires(true)]
#[ensures(result@ == a@)]
fn copy(a: &Vec<u64>) -> Vec<u64> {
    let mut b = Vec::with_capacity(a.len());

    // Loop invariant: at each iteration
    //   1) b.len() never exceeds a.len()
    //   2) for all j < b.len(), b[j] == a[j]
    // And we decrease (a.len() - b.len()) so Verus can prove termination.
    #[invariant(b.len() <= a.len())]
    #[invariant(forall |j: usize| j < b.len() ==> b[j] == a[j])]
    #[decreases(a.len() - b.len())]
    for &item in a.iter() {
        b.push(item);
    }

    b
}

